SELECT 'C360-SEM-001' AS test_id, count(*) AS violations FROM (SELECT col0 FROM (VALUES ('domain'),('semantic'),('search'),('prediction'),('observability'),('memory')) m WHERE col0 NOT IN (SELECT module_name FROM semantic.data_product_map)) defects;
SELECT 'C360-SEM-002' AS test_id, count(*) AS violations FROM (SELECT col0 FROM (VALUES ('domain.customer_keymap'),('domain.customer'),('domain.product_keymap'),('domain.product'),('domain.account_keymap'),('domain.account'),('domain.transaction_keymap'),('domain.transaction'),('semantic.data_product_registry'),('semantic.data_product_map'),('semantic.entity_metadata'),('semantic.column_metadata'),('semantic.table_relationship'),('semantic.access_object'),('semantic.access_composition'),('semantic.primary_object'),('semantic.data_product_orientation'),('semantic.naming_standard'),('semantic.metric'),('semantic.metric_expression'),('semantic.metric_dataset'),('semantic.semantic_synonym'),('semantic.model_metadata'),('semantic.feature_definition'),('semantic.role_policy'),('memory.module_registry'),('memory.design_decision'),('memory.business_glossary'),('memory.query_cookbook'),('memory.implementation_note'),('memory.change_log'),('memory.agent_session'),('memory.agent_interaction'),('memory.learned_strategy'),('memory.user_preference'),('memory.discovered_pattern'),('search.entity_embedding'),('prediction.feature_value'),('prediction.model_prediction'),('observability.change_event'),('observability.data_quality_metric'),('observability.lineage_run'),('observability.model_performance'),('observability.agent_outcome'),('observability.data_lineage'),('observability.retention_policy'),('observability.validation_run'),('observability.validation_area'),('observability.validation_check')) e WHERE col0 NOT IN (SELECT entity_name FROM semantic.entity_metadata)) defects;
SELECT 'C360-SEM-003' AS test_id, count(*) AS violations FROM (SELECT t.schema_name,t.table_name FROM duckdb_tables() t
        LEFT JOIN semantic.entity_metadata e ON e.container_name=t.schema_name AND e.table_name=t.table_name
        WHERE t.database_name=current_database() AND NOT t.internal AND e.entity_name IS NULL) defects;
SELECT 'C360-SEM-004' AS test_id, count(*) AS violations FROM (SELECT e.entity_name FROM semantic.entity_metadata e LEFT JOIN duckdb_tables() t
        ON t.database_name=current_database() AND t.schema_name=e.container_name AND t.table_name=e.table_name WHERE t.table_name IS NULL) defects;
SELECT 'C360-SEM-005' AS test_id, count(*) AS violations FROM (SELECT p.object_identity FROM semantic.primary_object p LEFT JOIN duckdb_views() v
        ON v.database_name=current_database() AND v.schema_name||'.'||v.view_name=p.object_identity WHERE v.view_name IS NULL
        OR p.object_role NOT IN ('AGENT_ENTRYPOINT','ANALYTICAL_QUERY','REFERENCE_LOOKUP','RELATIONSHIP_BRIDGE','LINEAGE_EVIDENCE','OPERATIONAL_METRIC','WRITE_TARGET','INTERNAL_SUPPORT')) defects;
SELECT 'C360-SEM-006' AS test_id, count(*) AS violations FROM (SELECT a.object_identity FROM semantic.access_object a LEFT JOIN semantic.entity_metadata e ON a.represents_entity=e.entity_name
        WHERE a.access_role<>'COMPOSITE' AND e.entity_name IS NULL
        UNION ALL SELECT composite_object FROM semantic.access_composition GROUP BY composite_object HAVING count(*) FILTER(WHERE member_role='ANCHOR')<>1) defects;
SELECT 'C360-SEM-007' AS test_id, count(*) AS violations FROM (SELECT a.object_identity FROM semantic.access_object a LEFT JOIN duckdb_views() v
        ON v.database_name=current_database() AND v.schema_name||'.'||v.view_name=a.object_identity
        WHERE a.is_agent_consumable AND v.view_name IS NULL) defects;
SELECT 'C360-SEM-008' AS test_id, count(*) AS violations FROM (SELECT resource_role FROM semantic.data_product_orientation o LEFT JOIN duckdb_views() v
        ON v.database_name=current_database() AND v.schema_name||'.'||v.view_name=o.object_identity
        WHERE o.is_required AND v.view_name IS NULL) defects;
SELECT 'C360-SEM-009' AS test_id, count(*) AS violations FROM (SELECT role FROM (VALUES ('MANIFEST'),('TRUST_MAP'),('MODULE_MAP'),('OBJECT_CATALOGUE'),('ENTITY_CATALOGUE'),('COLUMN_CATALOGUE'),('RELATIONSHIP_CATALOGUE')) r(role)
        WHERE NOT EXISTS(SELECT 1 FROM semantic.data_product_orientation o WHERE o.resource_role=r.role AND o.is_required)
        UNION ALL SELECT resource_role FROM semantic.data_product_orientation WHERE resource_role NOT IN ('MANIFEST','TRUST_MAP')
        AND discovery_order <= (SELECT discovery_order FROM semantic.data_product_orientation WHERE resource_role='TRUST_MAP')) defects;
SELECT 'C360-SEM-010' AS test_id, count(*) AS violations FROM (SELECT entity_name FROM semantic.entity_metadata e WHERE standalone_reason IS NULL AND NOT EXISTS
        (SELECT 1 FROM semantic.table_relationship r WHERE e.entity_name IN (r.source_entity,r.target_entity))) defects;
SELECT 'C360-SEM-011' AS test_id, count(*) AS violations FROM (SELECT m.metric_name FROM semantic.metric m WHERE NOT EXISTS(SELECT 1 FROM semantic.metric_expression x WHERE x.metric_name=m.metric_name)
        OR (SELECT count(*) FROM semantic.metric_dataset d WHERE d.metric_name=m.metric_name AND d.dataset_role='PRIMARY')<>1
        UNION ALL SELECT d.metric_name FROM semantic.metric_dataset d LEFT JOIN semantic.entity_metadata e ON e.entity_name=d.entity_name WHERE e.entity_name IS NULL) defects;
SELECT 'C360-SEM-012' AS test_id, count(*) AS violations FROM (SELECT synonym_id FROM semantic.semantic_synonym s WHERE
        (object_kind='ENTITY' AND NOT EXISTS(SELECT 1 FROM semantic.entity_metadata e WHERE e.entity_name=s.object_name)) OR
        (object_kind='COLUMN' AND NOT EXISTS(SELECT 1 FROM semantic.column_metadata c WHERE c.column_metadata_id=s.object_name)) OR
        (object_kind='METRIC' AND NOT EXISTS(SELECT 1 FROM semantic.metric m WHERE m.metric_name=s.object_name)) OR object_kind NOT IN ('ENTITY','COLUMN','METRIC')) defects;
