SELECT 'C360-REL-027' AS test_id, count(*) AS violations FROM (SELECT 'memory.change_log' WHERE NOT EXISTS(SELECT 1 FROM semantic.table_relationship WHERE source_entity='memory.change_log' AND source_column='related_decision_id' AND target_entity='memory.design_decision' AND target_column='decision_id')) defects;
SELECT 'C360-SEARCH-001' AS test_id, count(*) AS violations FROM (SELECT embedding_id FROM search.entity_embedding e LEFT JOIN semantic.model_metadata m ON e.embedding_model=m.model_key
        WHERE m.model_key IS NULL OR e.embedding_model_version<>m.model_version OR e.embedding_dimensions<>m.dimensions
        OR array_length(e.embedding)<>e.embedding_dimensions OR NOT isfinite(array_inner_product(e.embedding,e.embedding)) OR array_inner_product(e.embedding,e.embedding)<=0) defects;
SELECT 'C360-PRED-001' AS test_id, count(*) AS violations FROM (SELECT feature_value_id FROM prediction.feature_value WHERE observation_dts>valid_from_dts OR value_numeric NOT BETWEEN 0 AND 1) defects;
SELECT 'C360-PRED-002' AS test_id, count(*) AS violations FROM (SELECT p.prediction_id FROM prediction.model_prediction p LEFT JOIN prediction.feature_value f
        ON p.entity_id=f.entity_id AND p.feature_observation_dts=f.observation_dts
        WHERE f.feature_value_id IS NULL OR f.observation_dts>p.prediction_dts OR p.prediction_dts<p.valid_from_dts
        OR p.prediction_value<>1-f.value_numeric) defects;
SELECT 'C360-PRED-003' AS test_id, count(*) AS violations FROM (SELECT f.feature_value_id FROM prediction.feature_value f WHERE NOT EXISTS
        (SELECT 1 FROM domain.customer c WHERE c.customer_id=f.entity_id AND c.valid_from_dts<=f.observation_dts AND f.observation_dts<c.valid_to_dts AND NOT c.is_deleted)) defects;
SELECT 'C360-PRED-004' AS test_id, count(*) AS violations FROM (SELECT p.prediction_id FROM prediction.model_prediction p JOIN semantic.model_metadata m USING(model_key)
        WHERE p.model_version<>m.model_version OR p.prediction_dts>p.valid_from_dts) defects;
SELECT 'C360-OBS-001' AS test_id, count(*) AS violations FROM (SELECT source_node FROM semantic.lineage_graph EXCEPT (SELECT source_table FROM observability.data_lineage WHERE is_active UNION SELECT job_name FROM observability.data_lineage WHERE is_active)) defects;
SELECT 'C360-OBS-002' AS test_id, count(*) AS violations FROM (SELECT policy_id FROM observability.retention_policy WHERE (policy_id='definitions' AND retention_days IS NOT NULL) OR (policy_id='events' AND retention_days IS NULL)) defects;
SELECT 'C360-DOC-domain' AS test_id, count(*) AS violations FROM (SELECT 'domain' WHERE
            (SELECT count(*) FROM memory.v_design_decision WHERE source_module='domain')<3 OR
            (SELECT count(*) FROM memory.v_business_glossary WHERE source_module='domain')<3 OR
            (SELECT count(*) FROM memory.v_query_cookbook WHERE source_module='domain')<1 OR
            (SELECT count(*) FROM memory.v_change_log WHERE source_module='domain')<1 OR
            (SELECT count(*) FROM memory.v_module_registry WHERE module_name='domain')<>1) defects;
SELECT 'C360-DOC-semantic' AS test_id, count(*) AS violations FROM (SELECT 'semantic' WHERE
            (SELECT count(*) FROM memory.v_design_decision WHERE source_module='semantic')<3 OR
            (SELECT count(*) FROM memory.v_business_glossary WHERE source_module='semantic')<3 OR
