SELECT 'C360-DOC-memory' AS test_id, count(*) AS violations FROM (SELECT 'memory' WHERE
            (SELECT count(*) FROM memory.v_design_decision WHERE source_module='memory')<3 OR
            (SELECT count(*) FROM memory.v_business_glossary WHERE source_module='memory')<3 OR
            (SELECT count(*) FROM memory.v_query_cookbook WHERE source_module='memory')<1 OR
            (SELECT count(*) FROM memory.v_change_log WHERE source_module='memory')<1 OR
            (SELECT count(*) FROM memory.v_module_registry WHERE module_name='memory')<>1) defects;
SELECT 'C360-DOC-SPECIAL' AS test_id, count(*) AS violations FROM (SELECT id FROM (VALUES ('DD-ACCESS-001'),('DD-DISCOVERY-001')) x(id)
        WHERE id NOT IN (SELECT decision_id FROM memory.v_design_decision)
        UNION ALL SELECT 'QC-SEMANTIC-002' WHERE NOT EXISTS(SELECT 1 FROM memory.v_query_cookbook WHERE recipe_id='QC-SEMANTIC-002')) defects;
SELECT 'C360-DOC-PAIRS' AS test_id, count(*) AS violations FROM (SELECT a.module_name,b.module_name FROM semantic.data_product_map a CROSS JOIN semantic.data_product_map b
        WHERE a.module_name<b.module_name AND NOT EXISTS(SELECT 1 FROM memory.v_query_cookbook c WHERE c.target_module='CROSS'
        AND (c.recipe_id='QC-CROSS-'||upper(a.module_name)||'-'||upper(b.module_name) OR c.recipe_id='QC-CROSS-'||upper(b.module_name)||'-'||upper(a.module_name)))) defects;
SELECT 'C360-PLACE-001' AS test_id, count(*) AS violations FROM (SELECT table_schema,table_name FROM information_schema.tables
        WHERE table_catalog=current_database() AND table_schema NOT IN ('domain','semantic','search','prediction','observability','memory')) defects;
SELECT 'C360-VAL-001' AS test_id, count(*) AS violations FROM (SELECT run_id FROM observability.validation_run WHERE total_checks<>passed_count+failed_count+error_count
        OR agent_use_allowed<>'go' OR payload_schema_version<>'2.1' OR producer_id IS NULL
        OR ((error_count>0 OR error_failure_count>0 OR critical_failure_count>0) AND trust_status<>'UNTRUSTED')) defects;
SELECT 'C360-VAL-002' AS test_id, count(*) AS violations FROM (SELECT area_id FROM observability.validation_area WHERE checks_ran<>passed_count+failed_count+error_count
        OR checks_ran>checks_expected OR (confidence='strong' AND (checks_ran<>checks_expected OR checks_ran=0 OR failed_count+error_count>0))
        OR (confidence<>'strong' AND (open_gaps IS NULL OR recommended_action IS NULL))
        OR (area_status IN ('no-evidence','not-validated') AND confidence<>'unknown')) defects;
SELECT 'C360-VAL-003' AS test_id, count(*) AS violations FROM (SELECT area_id FROM observability.validation_area a WHERE
        scope_kind NOT IN ('PRODUCT','MODULE','ENTITY','PATTERN','CAPABILITY') OR
        area_status NOT IN ('pass','fail','partial','not-validated','no-evidence') OR confidence NOT IN ('strong','partial','weak','unknown') OR
        (scope_kind='MODULE' AND scope_id NOT IN (SELECT module_name FROM semantic.data_product_map)) OR
        (scope_kind='ENTITY' AND scope_id NOT IN (SELECT entity_name FROM semantic.entity_metadata)) OR
        (scope_kind='PRODUCT' AND scope_id NOT IN (SELECT product_id FROM semantic.data_product_registry)) OR
        (scope_kind='PATTERN' AND scope_id NOT IN ('temporal-lifecycle-metadata','object-placement','physical-storage','validation','access-layer')) OR
        (scope_kind='CAPABILITY' AND scope_id NOT IN ('Embed'))) defects;
SELECT 'C360-VAL-004' AS test_id, count(*) AS violations FROM (SELECT c.check_result_id FROM observability.validation_check c LEFT JOIN observability.validation_area a
        ON c.run_id=a.run_id AND c.scope_kind=a.scope_kind AND c.scope_id=a.scope_id WHERE a.area_id IS NULL
        UNION ALL SELECT r.run_id FROM observability.validation_run r WHERE NOT EXISTS
        (SELECT 1 FROM observability.validation_area a WHERE a.run_id=r.run_id)) defects;
SELECT 'C360-VAL-005' AS test_id, count(*) AS violations FROM (SELECT a.area_id FROM observability.validation_area a LEFT JOIN observability.validation_check c
        ON a.run_id=c.run_id AND a.scope_kind=c.scope_kind AND a.scope_id=c.scope_id
        GROUP BY a.area_id,a.checks_ran,a.passed_count,a.failed_count,a.error_count,a.critical_failure_count,a.error_failure_count
        HAVING a.checks_ran<>count(c.check_result_id) OR a.passed_count<>count(*) FILTER(WHERE c.status='PASSED')
        OR a.failed_count<>count(*) FILTER(WHERE c.status='FAILED') OR a.error_count<>count(*) FILTER(WHERE c.status='ERROR')
        OR a.critical_failure_count<>count(*) FILTER(WHERE c.status<>'PASSED' AND c.severity='CRITICAL')
        OR a.error_failure_count<>count(*) FILTER(WHERE c.status<>'PASSED' AND c.severity='ERROR')) defects;
